def footer(prefix=''):
 return f'''<footer><div class="footer-main wrap"><div><a class="brand" href="{prefix}index.html"><img src="{prefix}assets/logo.webp" alt="" width="42" height="46"><span>UNITY<span class="brand-sub">ENGINEERING</span></span></a><p>Process equipment fabrication.<br>Established 2006 · Ankleshwar, India.</p></div><div><h3>Explore</h3><a href="{prefix}index.html#products">Equipment catalogue</a><a href="{prefix}index.html#about">About Unity</a><a href="{prefix}index.html#fabrication">Fabrication</a></div><div><h3>Get in touch</h3><a href="tel:+919934969351">{phone}</a><a href="mailto:{email}">{email}</a><a href="{mapurl}" target="_blank" rel="noopener">Ankleshwar GIDC, Gujarat ↗</a></div></div><div class="footer-end wrap"><span>© <span data-year>2026</span> Unity Engineering.</span><span>Equipment visuals are illustrative 3D models, not actual photographs or fabrication drawings.</span></div></footer>'''
def head(title,desc,prefix=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><meta name="theme-color" content="#101316"><link rel="icon" href="{prefix}assets/favicon.png"><link rel="stylesheet" href="{prefix}assets/style.css"><script defer src="{prefix}assets/engine.js"></script><script defer src="{prefix}assets/app.js"></script></head>'''
def card(p,prefix=''):
 return f'''<article class="product-card" data-category="{p['cat']}" data-search="{E((p['title']+' '+categories[p['cat']][0]).lower())}"><a class="product-img" href="{prefix}products/{p['slug']}.html"><img src="{prefix}assets/products/{p['kind']}.webp" alt="Illustrative 3D model of {E(p['title'])}" loading="lazy" width="420" height="330"><span class="model-tag">3D MODEL</span></a><div class="product-copy"><span class="eyebrow">{E(categories[p['cat']][0])}</span><h3><a href="{prefix}products/{p['slug']}.html">{E(p['title'])}</a></h3><a class="text-link" href="{prefix}products/{p['slug']}.html">Explore equipment <span>↗</span></a></div></article>'''
catcards=''.join(f'''<button class="category-card" data-filter="{i}" type="button"><span class="cat-index">0{i+1} / {len(c[3]):02d} ENTRIES</span><img src="assets/products/{c[2]}.webp" alt="" loading="lazy" width="420" height="330"><span class="cat-title">{E(c[0])} <b>↗</b></span><span class="cat-sub">{E(c[1])}</span></button>''' for i,c in enumerate(categories))
filters='<button class="chip active" data-filter="all" aria-pressed="true">All equipment</button>'+''.join(f'<button class="chip" data-filter="{i}" aria-pressed="false">{E(c[0])}</button>' for i,c in enumerate(categories))
opts=''.join(f'<option>{E(p["title"])}</option>' for p in products)
